  "funnel-chart": {
    "key": "funnel-chart",
    "selector": "ds-funnel-chart",
    "isElement": true,
    "className": "FunnelChartComponent",
    "status": "stable",
    "importName": "FunnelChartComponent",
    "importPath": "@ids-group-ltd/ids-design-system",
    "entryPoint": "@ids-group-ltd/ids-design-system/components/funnel-chart",
    "summary": null,
    "inputs": [
      {
        "name": "frame",
        "kind": "input",
        "type": "ChartFrame | null",
        "union": [
          "auto",
          "none"
        ],
        "default": "null",
        "required": false,
        "description": "`'auto'` draws the chart's own bordered, padded box; `'none'` leaves it bare, for a chart inside a card. Unset falls back to `DS_CONFIG.chart.frame`, then `'auto'`."
      },
      {
        "name": "caption",
        "kind": "input",
        "type": "string | null",
        "union": null,
        "default": "null",
        "required": false,
        "description": "Visible title above the plot, reused as the annex table's caption."
      },
      {
        "name": "summary",
        "kind": "input",
        "type": "string | null",
        "union": null,
        "default": "null",
        "required": false,
        "description": "Accessible name. Generated from the data when omitted."
      },
      {
        "name": "loading",
        "kind": "input",
        "type": "boolean",
        "union": null,
        "default": "false",
        "required": false,
        "description": "With no data, draws a skeleton in the chart's shape: `skeletonCount` marks where the chart has it, the data's count once known. With data on screen, keeps the plot under `ds-loading-overlay`."
      },
      {
        "name": "error",
        "kind": "input",
        "type": "boolean",
        "union": null,
        "default": "false",
        "required": false,
        "description": "Shows `errorText` in place of the plot. Separate from `loading` and from empty data."
      },
      {
        "name": "emptyText",
        "kind": "input",
        "type": "string | null",
        "union": null,
        "default": "null",
        "required": false,
        "description": "Shown when there is no data. Unset falls back to `DS_INTL.chart.empty`."
      },
      {
        "name": "errorText",
        "kind": "input",
        "type": "string | null",
        "union": null,
        "default": "null",
        "required": false,
        "description": "The message the error state prints. Unset falls back to `DS_INTL.chart.error`."
      },
      {
        "name": "valueFormat",
        "kind": "input",
        "type": "ChartValueFormat | null",
        "union": null,
        "default": "null",
        "required": false,
        "description": "Formats every printed value, including the annex table and generated description. Unset falls back to `DS_CONFIG.chart.valueFormat`, then `DS_CONFIG.locale` / `LOCALE_ID`."
      },
      {
        "name": "interactive",
        "kind": "input",
        "type": "boolean",
        "union": null,
        "default": "false",
        "required": false,
        "description": "Turns on the click affordance: pointer cursor and hover tint. The click output fires whether or not this is set."
      },
      {
        "name": "tooltipSwatches",
        "kind": "input",
        "type": "boolean | null",
        "union": null,
        "default": "null",
        "required": false,
        "description": "Whether the tooltip draws a colour dot beside each reading. Unset falls back to `DS_CONFIG.chart.tooltipSwatches`, then shows them for two to four readings."
      },
      {
        "name": "tooltipLingerMs",
        "kind": "input",
        "type": "number | null",
        "union": null,
        "default": "null",
        "required": false,
        "description": "How long the tooltip stays after the pointer leaves the mark for another part of the chart, in milliseconds; zero closes it at once. A pointer that leaves the chart closes it at once whatever this says. Unset falls back to `DS_CONFIG.chart.tooltipLingerMs`, then 500."
      },
      {
        "name": "pinOnClick",
        "kind": "input",
        "type": "boolean | null",
        "union": null,
        "default": "null",
        "required": false,
        "description": "Holds the clicked mark and its tooltip until a second click, Escape or a press outside. Unset falls back to `DS_CONFIG.chart.pinOnClick`, then `true`. The click output fires either way."
      },
      {
        "name": "highlightActive",
        "kind": "input",
        "type": "boolean | null",
        "union": null,
        "default": "null",
        "required": false,
        "description": "Whether the hovered or focused column, bar or heatmap cell brightens. Unset falls back to `DS_CONFIG.chart.highlightActive`, then `true`."
      },
      {
        "name": "data",
        "kind": "input",
        "type": "readonly FunnelChartStage[]",
        "union": null,
        "default": "[]",
        "required": false,
        "description": "Drawn in the order given; stages are never sorted, since their order is the meaning."
      },
      {
        "name": "shape",
        "kind": "input",
        "type": "FunnelChartShape",
        "union": [
          "taper",
          "width",
          "area"
        ],
        "default": "'area'",
        "required": false,
        "description": "What the silhouette encodes. `'area'` (default) makes each stage's area proportional to its value. `'width'` reads widths straight off the values, which collapses the tail of a steep funnel. `'taper'` encodes nothing: the shape is fixed."
      },
      {
        "name": "showTable",
        "kind": "input",
        "type": "boolean",
        "union": null,
        "default": "true",
        "required": false,
        "description": "The value, percent and drop table printed under the funnel. While on, `dataTable` is not rendered."
      },
      {
        "name": "dataTable",
        "kind": "input",
        "type": "ChartDataTable | null",
        "union": [
          "toggle",
          "visible",
          "none"
        ],
        "default": "null",
        "required": false,
        "description": "The label-and-value disclosure. Ignored while `showTable` is on. Unset falls back to `DS_CONFIG.chart.dataTable`, then `'none'`."
      },
      {
        "name": "drop",
        "kind": "input",
        "type": "FunnelChartDrop",
        "union": [
          "relative",
          "absolute",
          "none"
        ],
        "default": "'relative'",
        "required": false,
        "description": "What the Drop column reports: `'relative'` (default) the share that leaked at this stage, `'absolute'` the count, `'none'` no column."
      },
      {
        "name": "skeletonCount",
        "kind": "input",
        "type": "number",
        "union": null,
        "default": "CHART_SKELETON_COUNT",
        "required": false,
        "description": "How many stages the loading skeleton draws before the data is known."
      },
      {
        "name": "dimOthers",
        "kind": "input",
        "type": "boolean",
        "union": null,
        "default": "false",
        "required": false,
        "description": "Dims every OTHER mark while one is hovered or focused."
      },
      {
        "name": "staggerMs",
        "kind": "input",
        "type": "number",
        "union": null,
        "default": "60",
        "required": false,
        "description": "Milliseconds between one stage's entrance and the next, top to bottom; `0` turns it off. The step narrows to keep the spread within 260ms."
      },
      {
        "name": "tooltip",
        "kind": "input",
        "type": "ChartItemTooltipTrigger",
        "union": [
          "item",
          "none"
        ],
        "default": "'item'",
        "required": false,
        "description": "Whether a hovered or focused stage opens a tooltip."
      }
    ],
    "outputs": [
      {
        "name": "stageClicked",
        "kind": "output",
        "type": "FunnelChartStage",
        "union": null,
        "default": null,
        "required": false,
        "description": "The stage clicked or activated with Enter or Space, whether or not `interactive` is set."
      }
    ]
  },
